                        " / (SELECT   SUM (NVL (Total_defect, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy')) * 100),2)  MISS_MISPLACE_PER, " +

                             "trunc( ( (SELECT   SUM (NVL (PO_MAIN_SIZE_LBL_MISTAKE, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy'))" +
                        " / (SELECT   SUM (NVL (Total_defect, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy')) * 100),2)  PO_MAIN_SIZE_LBL_MISTAKE_PER, " +

                             "trunc( ( (SELECT   SUM (NVL (CHEST_WAIST, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy'))" +
                        " / (SELECT   SUM (NVL (Total_defect, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy')) * 100),2)  CHEST_WAIST_PER, " +

                             "trunc( ( (SELECT   SUM (NVL (F_BACK_LENGTH_THIGH, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy'))" +
                        " / (SELECT   SUM (NVL (Total_defect, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy')) * 100),2)  F_BACK_LENGTH_THIGH_PER, " +

                             "trunc( ( (SELECT   SUM (NVL (SLV_LENGTH_INSEAM, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy'))" +
                        " / (SELECT   SUM (NVL (Total_defect, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy')) * 100),2)  SLV_LENGTH_INSEAM_PER, " +

                             "trunc( ( (SELECT   SUM (NVL (SWEEP_HIP, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy'))" +
                        " / (SELECT   SUM (NVL (Total_defect, 0)) FROM   VEW_RPT_SEWING_DEFECT WHERE   head_office_id = '331' AND branch_office_id = '103' AND DEFECT_DATE BETWEEN TO_DATE ('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE ('" + objReportDTO.ToDate + "','dd/mm/yyyy')) * 100),2)  SWEEP_HIP_PER " +

