        public DataSet EmployeJobConfiramtionSheet(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";

                    if (objReportDTO.HeadOfficeId == "441")
                    {
                        sql = "SELECT " +
                               "REPORT_TITLE, " +
                               "HEAD_OFFICE_ID, " +
                               "HEAD_OFFICE_NAME, " +
                               "HEAD_OFFICE_ADDRESS, " +
                               "BRANCH_OFFICE_ID, " +
                               "BRANCH_OFFICE_NAME, " +
                               "BRANCH_OFFICE_ADDRESS, " +
                               "EMPLOYEE_ID, " +
                               "CARD_NO, " +
                               "EMPLOYEE_NAME, " +
                               "DESIGNATION_NAME, " +
                               "UNIT_NAME, " +
                               "SECTION_NAME, " +
                               "JOINING_DATE, " +
                               "TRAINING_PERIOD_NAME, " +
                               "CONFIRMATION_DATE, " +
                               "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                               "CONFIRMATION_YEAR, " +
                               "CONFIRMATION_MONTH " +

                            "from vew_employee_confirmation  where head_office_id = '" + objReportDTO.HeadOfficeId + "'  AND CONFIRMATION_YEAR = '" + objReportDTO.Year + "'  OR CONFIRMATION_DATE BETWEEN TO_DATE('" + objReportDTO.FromDate + "','dd/mm/yyyy') AND  TO_DATE('" + objReportDTO.ToDate + "','dd/mm/yyyy') ";


                        if (objReportDTO.EmployeeId.Length > 0)
                        {
                            sql = sql + "and employee_id = '" + objReportDTO.EmployeeId + "' ";

                        }
                        if (objReportDTO.Month.Length > 0)
                        {
                            sql = sql + "and CONFIRMATION_MONTH = '" + objReportDTO.Month + "' ";

                        }

                        if (objReportDTO.SectionId.Length > 0)
                        {
                            sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                        }


                        if (objReportDTO.UnitId.Length > 0)
                        {
                            sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";

                        }


                        if (objReportDTO.CardNo.Length > 0)
                        {
                            sql = sql + "and card_no = '" + objReportDTO.CardNo + "' ";

                        }


                        if (objReportDTO.FromMonthId.Length > 0 && objReportDTO.ToMonthId.Length > 0)
                        {
                            sql = sql + "and CONFIRMATION_MONTH BETWEEN TO_NUMBER('" + objReportDTO.FromMonthId + "') AND  TO_NUMBER('" + objReportDTO.ToMonthId + "') ";

                        }





                    }
                    else
                    {




                        sql = "SELECT " +
                                "REPORT_TITLE, " +
                                "HEAD_OFFICE_ID, " +
                                "HEAD_OFFICE_NAME, " +
                                "HEAD_OFFICE_ADDRESS, " +
                                "BRANCH_OFFICE_ID, " +
                                "BRANCH_OFFICE_NAME, " +
                                "BRANCH_OFFICE_ADDRESS, " +
                                "EMPLOYEE_ID, " +
                                "CARD_NO, " +
                                "EMPLOYEE_NAME, " +
                                "DESIGNATION_NAME, " +
                                "UNIT_NAME, " +
                                "SECTION_NAME, " +
                                "JOINING_DATE, " +
                                "TRAINING_PERIOD_NAME, " +
                                "CONFIRMATION_DATE, " +
                                "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                                "CONFIRMATION_YEAR, " +
                                "CONFIRMATION_MONTH " +

                                "from vew_employee_confirmation  where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' AND CONFIRMATION_YEAR = '" + objReportDTO.Year + "' AND confirmation_date is null ";


                        if (objReportDTO.EmployeeId.Length > 0)
                        {
                            sql = sql + "and employee_id = '" + objReportDTO.EmployeeId + "' ";

                        }
                        if (objReportDTO.Month.Length > 0)
                        {
                            sql = sql + "and CONFIRMATION_MONTH = '" + objReportDTO.Month + "' ";

                        }

                        if (objReportDTO.SectionId.Length > 0)
                        {
                            sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                        }
                        if (objReportDTO.UnitId.Length > 0)
                        {
                            sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";

                        }


                        if (objReportDTO.CardNo.Length > 0)
                        {
                            sql = sql + "and card_no = '" + objReportDTO.CardNo + "' ";

                        }



                        if (objReportDTO.FromMonthId.Length > 0 && objReportDTO.ToMonthId.Length > 0)
                        {
                            sql = sql + "and CONFIRMATION_MONTH BETWEEN TO_NUMBER(" + objReportDTO.FromMonthId + "') AND  TO_NUMBER('" + objReportDTO.ToMonthId + "') ";

                        }




                    }


                    sql = sql + " order by to_number(card_no) ";


                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "vew_employee_confirmation");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }
        public DataSet workerSalaryRange(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
