                       "SECTION_NAME_BANGLA, " +
                       "UNIT_ID, " +
                       "UNIT_NAME, " +
                       "UNIT_NAME_BANGLA, " +
                       "SALARY_RANGE, " +
                       "GROSS_SALARY, " +
                       "GRADE_NO, " +
                       "JOINING_DATE, " +
                        "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY " +

                        "from vew_worker_salary_range  where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "'";




                    if (objReportDTO.SectionId.Length > 0)
                    {
                        sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                    }
                    if (objReportDTO.UnitId.Length > 0)
                    {
                        sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";

                    }





                    //sql = sql + " order by to_number(card_no)";


