                           "from vew_salary_history where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' AND  SALARY_FROM_DATE = TO_DATE ('" + objReportDTO.FromDate + "', 'dd/mm/yyyy')  AND    SALARY_TO_DATE = TO_DATE ('" + objReportDTO.ToDate + "', 'dd/mm/yyyy')  and employee_id = '" + objReportDTO.EmployeeId + "' ";




