        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    
                    string sql = "";
                    sql = @"SELECT " +
                           "GROUP_OFFICE_NAME_ENG, " +
                           "HEAD_OFFICE_ID, " +
                           "HEAD_OFFICE_NAME, " +
                           "HEAD_OFFICE_ADDRESS, " +
                           "BRANCH_OFFICE_ID, " +
                           "BRANCH_OFFICE_NAME, " +
                           "EMPLOYEE_ID, " +
                           "EMPLOYEE_NAME, " +
                           "EMPLOYEE_NAME_BANGLA, " +
                           "CARD_NO, " +
                           "BASIC_SALARY, " +
                           "JOINING_DATE, " +
                           "ACCOUNT_NO, " +
                           "FIRST_SALARY, " +
                           "GROSS_SALARY, " +
                           "DESIGNATION_ID, " +
                           "DESIGNATION_NAME, " +
                           "UNIT_ID, " +
                           "UNIT_NAME, " +
                           "SECTION_ID, " +
                           "SECTION_NAME, " +
                           "CATAGORY_ID, " +
                           "CATAGORY_NAME, " +
                           "misc_sal, " +
                           "branch_office_address, " +
                           "grade_no, " +
                           "EMPLOYEE_TYPE_ID, " +
                           "ALLOWANCE_AMOUNT, " +
                           "GENDER_ID, " +
                           "GENDER_NAME, " +
                           "GENDER_NAME_ENGLISH, " +
                           "UNIT_GROUP_ID, ";
                    if (objReportDTO.ToDate != null)
                    {
                        objReportDTO.ToDate = "to_Date('" + objReportDTO.ToDate + "', 'dd/mm/yyyy')";
                        sql = sql + @" (SELECT   TRUNC (MONTHS_BETWEEN ("+ objReportDTO.ToDate + ", joining_date) / 12)"+
                        @" || ' e '
                        || TRUNC(
                              MOD(MONTHS_BETWEEN("+ objReportDTO.ToDate + ", joining_date), 12)"+
                           @")
                        || ' gv '
                        || TRUNC("+ objReportDTO.ToDate + " "+
                                @" - ADD_MONTHS(
                                      joining_date,
