                 FROM EMPLOYEE_JOB_DETAIl
                WHERE joining_date IS NOT NULL
                  AND employee_id = e.employee_id
                        AND head_office_id = e.head_office_id
                        AND branch_office_id = e.branch_office_id
                        )
                 TOTAL_YEAR ";
                    }
                    else
