        public DataSet monthlyTiffinRequisitionSummery(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT " +
                    "month_year, " +
                    "HEAD_OFFICE_ID, " +
                    "HEAD_OFFICE_NAME, " +
                    "HEAD_OFFICE_ADDRESS, " +
                    "BRANCH_OFFICE_ID, " +
                    "BRANCH_OFFICE_NAME, " +
                    "BRANCH_OFFICE_ADDRESS, " +
                    "UNIT_ID, " +
                    "UNIT_NAME, " +
                    "SECTION_ID, " +
                    "SECTION_NAME, " +
                    "TIFFIN_YEAR, " +
                    "TIFFIN_MONTH, " +
                    "TOTAL_EMPLOYEE, " +
                    "TOTAL_AMOUNT, " +
                    "PAYMENT_AMOUNT_BANGLA_TOTAL, " +
                    "requisitiion_unit, " +
                    "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +

                    " CASE " +
                    " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
                    "THEN " +
                    " (SELECT TOTAL_EMPLOYEE " +
                    " FROM VEW_TIFFIN_REQUISITION_SUMMERY " +
                    " WHERE head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                    " AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                    " AND TIFFIN_YEAR = '" + objReportDTO.Year + "' - 1 " +
                    " AND TIFFIN_MONTH = '12' " +
                    " AND unit_id = t.unit_id) " +

                    " ELSE " +
                    " (SELECT   TOTAL_EMPLOYEE " +
                    " FROM VEW_TIFFIN_REQUISITION_SUMMERY " +
                    " WHERE head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                    " AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                    " AND TIFFIN_YEAR = '" + objReportDTO.Year + "' " +
                    " AND TIFFIN_MONTH = '" + objReportDTO.Month + "' - 1 " +
                    " AND unit_id = t.unit_id) " +
                    " END " +
                    "  TOTAL_EMPLOYEE_PRE, " +

                    " CASE " +
                    " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
                    " THEN " +
                    " (SELECT   TOTAL_AMOUNT " +
                    " FROM  VEW_TIFFIN_REQUISITION_SUMMERY " +
                    " WHERE head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                    " AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                    " AND TIFFIN_YEAR = '" + objReportDTO.Year + "' - 1 " +
                    " AND TIFFIN_MONTH = '12' " +
                    " AND unit_id = t.unit_id) " +
                    " ELSE " +
                    " (SELECT   TOTAL_AMOUNT " +
                    " FROM   VEW_TIFFIN_REQUISITION_SUMMERY " +
                    " WHERE head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                    " AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                    " AND TIFFIN_YEAR = '" + objReportDTO.Year + "' " +
                    " AND TIFFIN_MONTH = '" + objReportDTO.Month + "' - 1 " +
                    " AND unit_id = t.unit_id) " +
                    " END " +
                    " TOTAL_AMOUNT_PRE, " +

                    "CASE " +
                    "WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
                    "THEN " +
                    " 'Tiffin Requisition Summery ' " +
                    " || (SELECT   month_name " +
                    " FROM L_MONTH_NAME " +
                    " WHERE   month_id = '12') " +
                    " || ', ' " +
                    " || to_char(tiffin_year " +
                    " - '1') " +
                    " ELSE " +
                    " TO_CHAR('Tiffin Requisition Summery ' " +
                    " || (SELECT   month_name " +
                    " FROM   L_MONTH_NAME " +
                    " WHERE   month_id = t.TIFFIN_month - '1') " +
                    " || ', ' " +
                    " || TIFFIN_YEAR) " +
                    " END " +
                    " PREVIOUS_MONTH_STATUS, " +

                    " 'Tiffin Requisition Summery ' " +
                    " || (SELECT   month_name " +
                    " FROM   L_MONTH_NAME " +
                    " WHERE   month_id = t.TIFFIN_month) " +
                    " || ', ' " +
                    " || tiffin_year " +
                    " CURRENT_MONTH_STATUS, " +
                    " TOTAL_TIFFIN_DAY, " +

                    " CASE " +
                    " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
                    " THEN " +
                    " (SELECT   TOTAL_TIFFIN_DAY " +
