                    " AND TIFFIN_MONTH = '12' " +
                    " AND unit_id = t.unit_id) " +
                    " ELSE " +
                    " (SELECT   TOTAL_TIFFIN_DAY " +
                    " FROM VEW_TIFFIN_REQUISITION_SUMMERY " +
                    " WHERE head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                    " AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                    " AND TIFFIN_YEAR = '" + objReportDTO.Year + "' " +
                    " AND TIFFIN_MONTH = '" + objReportDTO.Month + "' - 1 " +
                    " AND unit_id = t.unit_id) " +
                    " END " +
                    " TOTAL_TIFFIN_DAY_PRE " +
                    " from VEW_TIFFIN_REQUISITION_SUMMERY  t where  head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' AND TIFFIN_YEAR = '" + objReportDTO.Year + "' AND TIFFIN_MONTH = '" + objReportDTO.Month + "' ";

