        public DataTable GetTiffinRequisitionSummary(ReportDTO objReportDTO)
        {
            DataSet ds = null;
            DataTable myTable = new DataTable();
            try
            {
                string strMsg = "";

                OracleCommand objOracleCommand = new OracleCommand("SP_GET_WORKER_TIFFIN_SUMMARY");
                objOracleCommand.CommandType = CommandType.StoredProcedure;

                objOracleCommand.Parameters.Add("p_tiffin_year", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.Year;
                objOracleCommand.Parameters.Add("p_tiffin_month", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.Month;

                objOracleCommand.Parameters.Add("p_head_office_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.HeadOfficeId;
                objOracleCommand.Parameters.Add("p_branch_office_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.BranchOfficeId;
                objOracleCommand.Parameters.Add("p_logged_in_employee_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.UpdateBy;


                objOracleCommand.Parameters.Add("p_dbcursor", OracleDbType.RefCursor).Direction = ParameterDirection.Output;

                string VALUE = string.Empty;

                using (OracleConnection strConn = GetConnection())
                {
                    try
                    {
                        objOracleCommand.Connection = strConn;
                        strConn.Open();
                        trans = strConn.BeginTransaction();
                        myTable.Load(objOracleCommand.ExecuteReader());
                        trans.Commit();
                        strConn.Close();
                    }
                    catch (Exception ex)
                    {
                        throw new Exception("Error : " + ex.Message);
                    }
                    finally
                    {
                        strConn.Close();
                    }
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
            return myTable;
        }

