        public DataSet rptOverTimeRequsitionSummery(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT " +
                           //"decode('" + objReportDTO.Month + "',1,'JANUARY ',2,'FEBRUARY ',3,'MARCH ',4,'APRIL ',5,'MAY ',6,'JUNE ',7,'JULY ',8,'AUGUST ',9,'SEPTEMBER ',10,'OCTOBER ',11,'NOVEMBER ',12,'DECEMBER ','')|| '" + objReportDTO.Year + "' Month_YEAR, " +

                           "month_year, " +
                           "HEAD_OFFICE_ID, " +
                           "HEAD_OFFICE_NAME, " +
                           "HEAD_OFFICE_ADDRESS, " +
                           "BRANCH_OFFICE_ID, " +
                           "BRANCH_OFFICE_NAME, " +
                           "BRANCH_OFFICE_ADDRESS, " +
                           "UNIT_ID, " +
                           "UNIT_NAME, " +
                           "SECTION_ID, " +
                           "SECTION_NAME, " +
                           "OT_YEAR, " +
                           "OT_MONTH, " +
                           "TOTAL_EMPLOYEE, " +
                           "OVER_TIME_HOUR, " +
                           "TOTAL_AMOUNT, " +
                           "PAYMENT_AMOUNT_BANGLA_TOTAL, " +
                           "requisitiion_unit, " +
                           "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                           "payment_date, " +
                           "UNIT_NEW, " +




                                " CASE " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   TOTAL_EMPLOYEE " +
              "    FROM   VEW_OVER_TIME_REQUISITION_SUMM " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                 "        AND OT_YEAR = '" + objReportDTO.Year + "' - 1 " +
                  "       AND OT_MONTH = '12' " +
                   "      AND unit_id = t.unit_id) " +
            " ELSE " +
              " (SELECT   TOTAL_EMPLOYEE " +
               "   FROM   VEW_OVER_TIME_REQUISITION_SUMM " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  "       AND OT_YEAR = '" + objReportDTO.Year + "' " +
                   "      AND OT_MONTH = '" + objReportDTO.Month + "' - 1 " +
                    "     AND unit_id = t.unit_id) " +
        " END " +
          "  TOTAL_EMPLOYEE_PRE, " +


               " CASE " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   OVER_TIME_HOUR " +
              "    FROM   VEW_OVER_TIME_REQUISITION_SUMM " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                 "        AND OT_YEAR = '" + objReportDTO.Year + "' - 1 " +
                  "       AND OT_MONTH = '12' " +
                   "      AND unit_id = t.unit_id) " +
            " ELSE " +
              " (SELECT   OVER_TIME_HOUR " +
               "   FROM   VEW_OVER_TIME_REQUISITION_SUMM " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  "       AND OT_YEAR = '" + objReportDTO.Year + "' " +
                   "      AND OT_MONTH = '" + objReportDTO.Month + "' - 1 " +
                    "     AND unit_id = t.unit_id) " +
        " END " +
          "  OVER_TIME_HOUR_PRE, " +

           " CASE " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   TOTAL_AMOUNT " +
              "    FROM   VEW_OVER_TIME_REQUISITION_SUMM " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                 "        AND OT_YEAR = '" + objReportDTO.Year + "' - 1 " +
                  "       AND OT_MONTH = '12' " +
                   "      AND unit_id = t.unit_id) " +
            " ELSE " +
              " (SELECT   TOTAL_AMOUNT " +
               "   FROM   VEW_OVER_TIME_REQUISITION_SUMM " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  "       AND OT_YEAR = '" + objReportDTO.Year + "' " +
                   "      AND OT_MONTH = '" + objReportDTO.Month + "' - 1 " +
                    "     AND unit_id = t.unit_id) " +
        " END " +
          "  TOTAL_AMOUNT_PRE, " +

            "CASE " +
            "WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  'Over Time Requisition Summery ' " +
              "          || (SELECT   month_name " +
               "               FROM   L_MONTH_NAME " +
                "             WHERE   month_id = '12') " +
                 "       || ', ' " +
                  "      || to_char(ot_year " +
                   "     - '1') " +
         "   ELSE " +
          "     TO_CHAR('Over Time Requisition Summery ' " +
           "             || (SELECT   month_name " +
            "                  FROM   L_MONTH_NAME " +
             "                WHERE   month_id = t.OT_MONTH - '1') " +
              "          || ', ' " +
               "         || OT_YEAR) " +
