                              "  AND salary_year = '" + objReportDTO.Year + "' - 1 " +
                              "  AND salary_month = '12'), 0) " +

                           " ELSE " +
                             " NVL( (SELECT PAYMENT_AMOUNT_ADVANCE " +
                              "   FROM SALARY_REQUISITION_SUMMERY " +
                               "  WHERE head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                                " AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                                " and unit_id = s.unit_id " +
                                " AND salary_year = '" + objReportDTO.Year + "' " +
                                " AND salary_month = '" + objReportDTO.Month + "' - 1), 0) " +
                          " END " +
                          " PAYMENT_AMOUNT_ADVANCE_PRE, " +

                           "PAYMENT_AMOUNT_BANGLA_TOTAL, " +
                           "TOTAL_AMOUNT, " +
                           "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                           "UNIT_NEW, " +

                            "CASE " +
            "WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  'Salary Requisition Summary ' " +
              "          || (SELECT   month_name " +
               "               FROM   L_MONTH_NAME " +
                "             WHERE   month_id = '12') " +
                 "       || ', ' " +
                  "      || to_char('" + objReportDTO.Year + "' " +
                   "     - '1') " +
         "   ELSE " +
          "     TO_CHAR('Salary Requisition Summary ' " +
           "             || (SELECT   month_name " +
            "                  FROM   L_MONTH_NAME " +
             "                WHERE   month_id = '" + objReportDTO.Month + "' - '1') " +
              "          || ', ' " +
               "         || '" + objReportDTO.Year + "') " +
       "  END " +
        "    PRE_MONTH_STATUS, " +

          "  'Salary Requisition Summary ' " +
        " || (SELECT   month_name " +
         "      FROM   L_MONTH_NAME " +
          "    WHERE   month_id ='" + objReportDTO.Month + "') " +
        " || ', ' " +
        " ||  '" + objReportDTO.Year + "' " +
         "   CURR_MONTH_STATUS, " +

                                " CASE " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   TOTAL_EMPLOYEE " +
              "    FROM   VEW_SALARY_REQUISITION_SUMMERY " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                " and unit_id = s.unit_id " +
                 "        AND salary_year = '" + objReportDTO.Year + "' - 1 " +
                  "       AND salary_month = '12') " +

            " ELSE " +
              " (SELECT   TOTAL_EMPLOYEE " +
               "   FROM   VEW_SALARY_REQUISITION_SUMMERY " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  " and unit_id = s.unit_id " +
                  "       AND salary_year = '" + objReportDTO.Year + "' " +
                   "      AND salary_month = '" + objReportDTO.Month + "' - 1) " +

        " END " +
          "  TOTAL_EMPLOYEE_PRE, " +


            " CASE " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   REVENUE_FEE " +
              "    FROM   VEW_SALARY_REQUISITION_SUMMERY " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                " and unit_id = s.unit_id " +
                 "        AND salary_year = '" + objReportDTO.Year + "' - 1 " +
                  "       AND salary_month = '12') " +

            " ELSE " +
              " (SELECT   REVENUE_FEE " +
               "   FROM   VEW_SALARY_REQUISITION_SUMMERY " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  " and unit_id = s.unit_id " +
                  "       AND salary_year = '" + objReportDTO.Year + "' " +
                   "      AND salary_month = '" + objReportDTO.Month + "' - 1) " +

        " END " +
          "  REVENUE_FEE_PRE, " +


                                " CASE " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   OVER_TIME_HOUR " +
              "    FROM   VEW_SALARY_REQUISITION_SUMMERY " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                 " and unit_id = s.unit_id " +
                 "        AND salary_year = '" + objReportDTO.Year + "' - 1 " +
                  "       AND salary_month = '12') " +

            " ELSE " +
              " (SELECT   OVER_TIME_HOUR " +
               "   FROM   VEW_SALARY_REQUISITION_SUMMERY " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  " and unit_id = s.unit_id " +
                  "       AND salary_year = '" + objReportDTO.Year + "' " +
                   "      AND salary_month = '" + objReportDTO.Month + "' - 1) " +

        " END " +
          "  OVER_TIME_HOUR_PRE, " +


            " CASE " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   round(OVER_TIME_AMOUNT) " +
              "    FROM   VEW_SALARY_REQUISITION_SUMMERY " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                 " and unit_id = s.unit_id " +
                 "        AND salary_year = '" + objReportDTO.Year + "' - 1 " +
                  "       AND salary_month = '12') " +

            " ELSE " +
              " (SELECT    round(OVER_TIME_AMOUNT) " +
               "   FROM   VEW_SALARY_REQUISITION_SUMMERY " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  " and unit_id = s.unit_id " +
                  "       AND salary_year = '" + objReportDTO.Year + "' " +
                   "      AND salary_month = '" + objReportDTO.Month + "' - 1) " +

        " END " +
          "  OVER_TIME_AMOUNT_PRE, " +

           " CASE " +
           " WHEN s.section_id = '1001' then 0 " +
           " WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
            "THEN " +
             "  (SELECT   ATTENDENCE_FEE " +
              "    FROM   VEW_SALARY_REQUISITION_SUMMERY " +
               "  WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                 " and unit_id = s.unit_id " +
                 "        AND salary_year = '" + objReportDTO.Year + "' - 1 " +
                  "       AND salary_month = '12') " +

            " ELSE " +
              " (SELECT    ATTENDENCE_FEE " +
               "   FROM   VEW_SALARY_REQUISITION_SUMMERY " +
                " WHERE       head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                 "        AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
                  " and unit_id = s.unit_id " +
                  "       AND salary_year = '" + objReportDTO.Year + "' " +
                   "      AND salary_month = '" + objReportDTO.Month + "' - 1) " +

        " END " +
          "  ATTENDENCE_FEE_PRE, " +
          " CASE " +

     "WHEN '" + objReportDTO.Month + "' = 01 OR '" + objReportDTO.Month + "' = 1 " +
         "   THEN " +
          "     ((SELECT   SUM(ROUND(NVL(PAYMENT_AMOUNT, 0))) " +
           "         FROM   SALARY_REQUISITION_summery " +
           "        WHERE       SALARY_YEAR = '" + objReportDTO.Year + "' - 1 " +
               "               AND SALARY_MONTH = 12 " +
              "             AND UNIT_ID = s.UNIT_ID " +
               "            AND HEAD_OFFICE_ID = '" + objReportDTO.HeadOfficeId + "' " +
                "           AND BRANCH_OFFICE_ID = '" + objReportDTO.BranchOfficeId + "') " +

                //Asad added on 03.07.2019: December
                " + (SELECT   SUM(ROUND(NVL(PAYMENT_AMOUNT_ADVANCE, 0))) " +
           " FROM SALARY_REQUISITION_summery " +
           "        WHERE       SALARY_YEAR = '" + objReportDTO.Year + "' - 1 " +
               "               AND SALARY_MONTH = 12 " +
              "             AND UNIT_ID = s.UNIT_ID " +
               "            AND HEAD_OFFICE_ID = '" + objReportDTO.HeadOfficeId + "' " +
                "           AND BRANCH_OFFICE_ID = '" + objReportDTO.BranchOfficeId + "') " +


               " - ROUND(ABS((SELECT(ABS(NVL(OVER_TIME_AMOUNT, 0))) " +
                "                FROM   SALARY_REQUISITION_summery " +
                  "        WHERE       SALARY_YEAR = '" + objReportDTO.Year + "' - 1 " +
               "               AND SALARY_MONTH = 12 " +
                   "                    AND UNIT_ID = s.UNIT_ID " +

                     "                  AND HEAD_OFFICE_ID = '" + objReportDTO.HeadOfficeId + "' " +
                      "                 AND BRANCH_OFFICE_ID = " +
                       "                      '" + objReportDTO.BranchOfficeId + "') " +
                        "    + (SELECT(ABS(NVL(ATTENDENCE_FEE, 0))) " +
                         "        FROM   SALARY_REQUISITION_summery " +
                        "        WHERE       SALARY_YEAR = '" + objReportDTO.Year + "' - 1  " +
               "               AND SALARY_MONTH = 12 " +
                            "            AND UNIT_ID = s.UNIT_ID " +

                              "          AND HEAD_OFFICE_ID = '" + objReportDTO.HeadOfficeId + "' " +
                               "         AND BRANCH_OFFICE_ID = " +
                                "              '" + objReportDTO.BranchOfficeId + "')))) " +
          "  ELSE " +
           "    ((SELECT   SUM(ROUND(NVL(PAYMENT_AMOUNT, 0))) " +
            "        FROM   SALARY_REQUISITION_summery " +
              "        WHERE       SALARY_YEAR = '" + objReportDTO.Year + "' " +
               "               AND SALARY_MONTH = '" + objReportDTO.Month + "' -1  " +
               "            AND UNIT_ID = s.UNIT_ID " +
                "           AND HEAD_OFFICE_ID = '" + objReportDTO.HeadOfficeId + "' " +
