     "    END " +
           " TOTAL_AMOUNT_PRE_WITH_REVENUE,  " +

           "REVENUE_FEE, " +
           "TOTAL_AMOUNT_WITH_REVENUE " +
           "from VEW_SAL_REQUISI_SUMMERY_STAFF s  where  head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' and SALARY_YEAR = '" + objReportDTO.Year + "' and SALARY_MONTH = '" + objReportDTO.Month + "'  ";

                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "VEW_SAL_REQUISI_SUMMERY_STAFF");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }


