        public DataSet rptWorkerOverTimeSheet(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT " +
                        "' From ' ||  '" + objReportDTO.FromDate + "' || ' to ' ||  '" + objReportDTO.ToDate + "'  month_year, " +

                        "GROUP_OFFICE_NAME_ENG, " +
                       "EMPLOYEE_ID, " +
                       "EMPLOYEE_NAME, " +
                       "EMPLOYEE_CODE, " +
                       "CARD_NO, " +
                       "UNIT_ID, " +
                       "UNIT_NAME, " +
                       "SECTION_ID, " +
                       "SECTION_NAME, " +
                       "CATAGORY_ID, " +
                       "CATAGORY_NAME, " +
                       "FIRST_IN, " +
                       "LAST_OUT, " +
                       "FIRST_LATE_HOUR, " +
                       "FIRST_LATE_MINUTE, " +
                       "LUNCH_OUT, " +
                       "LUNCH_IN, " +
                       "LUNCH_LATE_HOUR, " +
                       "LUNCH_LATE_MINUTE, " +
                       "OT_HOUR, " +
                       "LOG_DATE, " +
                       "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                       "UPDATE_DATE, " +
                       "HEAD_OFFICE_ID, " +
                       "HEAD_OFFICE_NAME, " +
                       "HEAD_OFFICE_ADDRESS, " +
                       "BRANCH_OFFICE_ID, " +
                       "BRANCH_OFFICE_NAMEM, " +
                       "DESIGNATION_NAME, " +
                       "LOG_LATE, " +
                       "LUNCH_LATE, " +
                       "total_ot_hour, " +
                       "total_ot_minute, " +

                       "to_char(total_ot_hour) || to_char(total_ot_minute) over_time, " +

                       "(SELECT   sum (TOTAL_DAY)  FROM   holiday  WHERE     HOLIDAY_START_DATE >= to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and  HOLIDAY_END_DATE <= to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') " +
                       "AND head_office_id = s.head_office_id and branch_office_id = s.branch_office_id)total_holiday, " +

                        "(SELECT  ABS(to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') - to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy')) + 1  FROM   DUAL  " +
                       ")total_Day, " +

                       "(SELECT   sum (TOTAL_LEAVE)  FROM   EMPLOYEE_LEAVE  WHERE     LEAVE_START_DATE >= to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and LEAVE_END_DATE <=  to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') " +
                       "AND head_office_id = s.head_office_id and branch_office_id = s.branch_office_id and employee_id = s.employee_id)total_leave_day, " +


                       "ABS(NVL((SELECT   sum (TOTAL_DAY)  FROM   holiday  WHERE     HOLIDAY_START_DATE >= to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and  HOLIDAY_END_DATE <= to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') " +
                       "AND head_office_id = s.head_office_id and branch_office_id = s.branch_office_id), 0) -  NVL((SELECT   sum (TOTAL_LEAVE)  FROM   EMPLOYEE_LEAVE  WHERE     LEAVE_START_DATE >= to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and LEAVE_END_DATE <=  to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') AND head_office_id = s.head_office_id and branch_office_id = s.branch_office_id and employee_id = s.employee_id), 0) - " +
                       "(SELECT  ABS(to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') - to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy')) FROM   DUAL  " +
                       "))total_absent_day, " +




                       "NVL((SELECT   COUNT ( * )  FROM   VEW_ATTENDENCE_SHEET_MONTHLY  WHERE     LOG_DATE BETWEEN to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') " +
                       "AND head_office_id = s.head_office_id and branch_office_id = s.branch_office_id and employee_id = s.employee_id and (FIRST_IN is not null and LAST_OUT is not null)), 0)total_present_day " +




                       "from VEW_ATTENDENCE_SHEET_MONTHLY  s where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' ";


                    if (objReportDTO.FromDate.Length > 6 && objReportDTO.ToDate.Length > 6)
                    {
                        sql = sql + "and log_date between to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and  to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') ";

                    }


                    if (objReportDTO.UnitId.Length > 0)
                    {
                        sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";

                    }

                    if (objReportDTO.CardNo.Length > 0)
                    {
                        sql = sql + "and card_no = '" + objReportDTO.CardNo + "' ";

                    }

                    if (objReportDTO.EmployeeId.Length > 0)
                    {
                        sql = sql + "and employee_id = '" + objReportDTO.EmployeeId + "' ";

                    }



                    if (objReportDTO.SectionId.Length > 0)
                    {
                        sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                    }

