            if (objReportDTO.FabricId.Length > 0)
            {

                objOracleCommand.Parameters.Add("p_fabric_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.FabricId;

            }
            else
            {

                objOracleCommand.Parameters.Add("p_fabric_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
            }


            if (objReportDTO.ConstructionId.Length > 0)
            {

                objOracleCommand.Parameters.Add("p_fabric_construction_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.ConstructionId;

            }
            else
            {

                objOracleCommand.Parameters.Add("p_fabric_construction_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
            }




            if (objReportDTO.ArtNo.Length > 0)
            {

                objOracleCommand.Parameters.Add("p_art_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.ArtNo;

            }
            else
            {

                objOracleCommand.Parameters.Add("p_art_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
            }




            objOracleCommand.Parameters.Add("p_update_by", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.UpdateBy;
            objOracleCommand.Parameters.Add("p_head_office_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.HeadOfficeId;
            objOracleCommand.Parameters.Add("p_branch_office_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.BranchOfficeId;


            objOracleCommand.Parameters.Add("P_MESSAGE", OracleDbType.Varchar2, 500).Direction = ParameterDirection.Output;

            using (OracleConnection strConn = GetConnection())
            {
                try
                {
                    objOracleCommand.Connection = strConn;
                    strConn.Open();
                    trans = strConn.BeginTransaction();
                    objOracleCommand.ExecuteNonQuery();
                    trans.Commit();
                    strConn.Close();
                    strMsg = objOracleCommand.Parameters["P_MESSAGE"].Value.ToString();
                }

                catch (Exception ex)
                {
                    throw new Exception("Error : " + ex.Message);

                }

                finally
                {

                    strConn.Close();
                }

            }
            return strMsg;
        }

