        public DataSet salarySheetWorker(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";

                    sql = "SELECT " +
                                              "GROUP_OFFICE_NAME_ENG, " +
                                              "Month_YEAR, " +
                                              "EMPLOYEE_ID, " +
                                              "EMPLOYEE_NAME, " +
                                              "EMPLOYEE_NAME_BANGLA, " +
                                              "HEAD_OFFICE_ID, " +
                                              "HEAD_OFFICE_NAME, " +
                                              "HEAD_OFFICE_BANGLA, " +
                                              "BRANCH_OFFICE_NAME, " +
                                              "HEAD_OFFICE_ADDRESS, " +
                                              "REGULAR_PAY, " +
                                              "ACCOUNT_NO, " +
                                              "net_payment_actual, " +
                                              "round_up_amount, " +
                                              "round_up_return_amount, " +
                                              "NET_SALARY, " +
                                              "SECTION_ID, " +
                                              "SECTION_NAME, " +
                                              "SECTION_NAME_BANGLA, " +
                                              "UNIT_ID, " +
                                              "UNIT_NAME, " +
                                              "UNIT_NAME_BANGLA, " +
                                              "CATAGORY_ID, " +
                                              "CATAGORY_NAME, " +
                                              "SALARY_YEAR, " +
                                              "SALARY_MONTH, " +
                                              "bkash_no, " +
                                              "WORKING_DAY, " +
                                              "PARTIAL_DAY, " +
                                              "TIFFIN_DAY, " +
                                              "LUNCH_DAY, " +
                                              "ABSENT_DAY, " +
                                              "OVER_TIME_HOUR, " +
                                              "OVER_TIME_RATE, " +
                                              "OVER_TIME_AMOUNT, " +
                                              "early_deptr_hour, " +
                                              "early_deptr_deduct_amount, " +
                                              "ATTENDENCE_FEE, " +
                                              "ABSENT_FEE, " +
                                              "MEDICAL_FEE, " +
                                              "HOUSE_RENT_FEE, " +
                                              "TAX_FEE, " +
                                              "CONVENCE_FEE, " +
                                              "FOOD_FEE, " +
                                              "EXTRA_FOOD_FEE, " +
                                              "ADVANCE_FEE, " +
                                              "ALLOWANCE_AMOUNT, " +
                                              "ARREAR_FEE, " +
                                              "GROSS_SALARY, " +
                                              "BASIC_SALARY, " +
                                              "PAYMENT_AMOUNT, " +
                                              "bkash_amount, " +
                                              "FULL_PAYMENT, " +
                                              "PARTIAL_PAYMENT, " +
                                              "UPDATE_DATE, " +
                                               "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                                              "SALARY_MONTH_NEW, " +
                                              "ABSENT_DEDUCT_EXTRA_FOOD_FEE,  " +
                                              "MONTH_DAY, " +
                                              "DESIGNATION_ID, " +
                                              "DESIGNATION_NAME, " +
                                              "DESIGNATION_NAME_BANGLA, " +
                                              "CARD_NO, " +
                                              "JOINING_DATE, " +
                                              "GRADE_NO, " +
                                              "PAYMENT_AMOUNT_ENG, " +
                                              "PAYMENT_AMOUNT_ENG_TOTAL, " +
                                              "PAYMENT_AMOUNT_BANGLA, " +
                                              "PAYMENT_AMOUNT_BANGLA_TOTAL, " +
                                              "branch_office_address, " +
                                              "branch_office_name_bangla, " +
                                              "unit_section, " +
                                              "NET_FOOD_FEE, " +
                                              "REVENUE_FEE, " +
                                              "payment_date " +
                                              "from VEW_SALARY_SHEET_WORKER where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' and salary_year = '" + objReportDTO.Year + "' and salary_month = '" + objReportDTO.Month + "' ";

                    if (objReportDTO.UnitId.Length > 0)
                    {
                        sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";
                    }
                    if (objReportDTO.SectionId.Length > 0)
                    {
                        sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";
                    }
                    if (objReportDTO.EmployeeId.Length > 0)
                    {
                        sql = sql + "and employee_id = '" + objReportDTO.EmployeeId + "' ";
                    }
                    if (objReportDTO.CardNo.Length > 0)
                    {
                        sql = sql + "and card_no = '" + objReportDTO.CardNo + "' ";
                    }

                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();
                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "VEW_SALARY_SHEET_WORKER");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }
                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);
                        }

                        finally
                        {
                            strConn.Close();
                        }
                    }
                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }
