        public DataSet PurchaseSheet(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT " +
                           "SL, " +
                        "INVOICE_NO, " +
                        "EMPLOYEE_ID, " +
                        "EMPLOYEE_NAME, " +
                        "CARD_NO, " +
                        "DESIGNATION_NAME, " +
                        "PRODUCT_SL_NO, " +
                        "REQUISITION_NO, " +
                        "REQUISITION_DATE, " +
                        "LEDGER_NO, " +
                        "UNIT_ID, " +
                        "UNIT_NAME, " +
                        "SECTION_ID, " +
                        "SECTION_NAME, " +
                        "MRR_NO, " +
                        "MRR_DATE, " +
                        "PURCHASE_DATE, " +
                        "PRICE, " +
                        "WARRANTY_PERIOD, " +
                        "PRODUCT_DESCRIPTION, " +
                        "SUPPLIER_NAME, " +
                        "REMARKS, " +
                        "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                        "UPDATE_DATE, " +
                        "HEAD_OFFICE_ID, " +
                        "HEAD_OFFICE_NAME, " +
                        "BRANCH_OFFICE_ID, " +
                        "BRANCH_OFFICE_NAME, " +
                        "BRANCH_OFFICE_ADDRESS, " +
                        "PURCHASE_QUANTITY, " +
                        "TRAN_ID, " +
                        "FILE_NAME, " +
                        "PRODUCT_ID, " +
                        "PRODUCT_NAME " +




                           "from VEW_SEARCH_PURCHASE_INFO where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' ";




                    if (objReportDTO.UnitId.Length > 0)
                    {
                        sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";

                    }

                    if (objReportDTO.SectionId.Length > 0)
                    {
                        sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                    }


                    if (objReportDTO.RequisitionNo.Length > 0)
                    {
                        sql = sql + "and REQUISITION_NO = '" + objReportDTO.RequisitionNo + "' ";

                    }


                    if (objReportDTO.ProductSLNo.Length > 0)
                    {
                        sql = sql + "and PRODUCT_SL_NO = '" + objReportDTO.ProductSLNo + "' ";

                    }

                    if (objReportDTO.ProductId.Length > 0)
                    {
                        sql = sql + "and PRODUCT_ID = '" + objReportDTO.ProductId + "' ";

                    }

                    if (objReportDTO.FromDate.Length > 6 && objReportDTO.ToDate.Length > 6)
                    {
                        sql = sql + "and PRODUCT_DATE BETWEEN TO_DATE( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') AND TO_DATE( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy')  ";

                    }




                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "VEW_SEARCH_PURCHASE_INFO");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }
