                    {
                        //sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";
                        sql = sql + " and leave_start_date between to_date('" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and to_date('" + objReportDTO.ToDate + "', 'dd/mm/yyyy')";
                    }
