        public DataTable SalaryAdjustRequisitionAccordingToGazette(ReportDTO objReportDTO)
        {

            DataSet ds = null;
            DataTable myTable = new DataTable();
            try
            {
                string strMsg = "";
                OracleTransaction objOracleTransaction;
                OracleCommand objOracleCommand = new OracleCommand("pro_salary_adjustment_req");
                objOracleCommand.CommandType = CommandType.StoredProcedure;

                if (objReportDTO.Year != "")
                {
                    objOracleCommand.Parameters.Add("p_salary_year", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.Year;
                }
                else
                {
                    objOracleCommand.Parameters.Add("p_salary_year", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
                }

                if (objReportDTO.Month != "")
                {
                    objOracleCommand.Parameters.Add("p_salary_month", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.Month;
                }
                else
                {
                    objOracleCommand.Parameters.Add("p_salary_month", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
                }
                objOracleCommand.Parameters.Add("p_increment_yn", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.IncrementYn;

                if (objReportDTO.UnitGroupId != "")
                {
                    objOracleCommand.Parameters.Add("p_unit_group_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.UnitGroupId;
                }
                else
                {
                    objOracleCommand.Parameters.Add("p_unit_group_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
                }
                if (objReportDTO.UnitId != "")
                {
                    objOracleCommand.Parameters.Add("p_unit_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.UnitId;
                }
                else
                {
                    objOracleCommand.Parameters.Add("p_unit_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
                }
                if (objReportDTO.SectionId != "")
                {
                    objOracleCommand.Parameters.Add("p_section_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.SectionId;
                }
                else
                {
                    objOracleCommand.Parameters.Add("p_section_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = null;
                }

                objOracleCommand.Parameters.Add("p_head_office_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.HeadOfficeId;
                objOracleCommand.Parameters.Add("p_branch_office_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.BranchOfficeId;
                objOracleCommand.Parameters.Add("p_logged_in_employee_id", OracleDbType.Varchar2, ParameterDirection.Input).Value = objReportDTO.UpdateBy;
                objOracleCommand.Parameters.Add("p_dbcursor", OracleDbType.RefCursor).Direction = ParameterDirection.Output;

                string VALUE = string.Empty;

                using (OracleConnection strConn = GetConnection())
                {
                    try
                    {
                        objOracleCommand.Connection = strConn;
                        strConn.Open();
                        trans = strConn.BeginTransaction();
                        //var tbl = objOracleCommand.ExecuteReader();
                        myTable.Load(objOracleCommand.ExecuteReader());
                        trans.Commit();
                        strConn.Close();
                    }
                    catch (Exception ex)
                    {
                        throw new Exception("Error : " + ex.Message);
                    }
                    finally
                    {
                        strConn.Close();
                    }
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
            return myTable;
        }
