        public DataSet rptFirstBonusSheet(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    if (objReportDTO.UnitId.Length > 0 && objReportDTO.SectionId.Length > 0)
                    {

                        sql = "SELECT " +
                               "SL, " +
                               "EID_NAME_BANGLA, " +
                               "MONTH_YEAR, " +
                               "EMPLOYEE_ID, " +
                               "EMPLOYEE_NAME, " +
                               "HEAD_OFFICE_NAME, " +
                               "HEAD_OFFICE_ADDRESS, " +
                               "BRANCH_OFFICE_NAME, " +
                               "BRANCH_OFFICE_ADDRESS, " +
                               "DESIGNATION_NAME, " +
                               "UNIT_NAME, " +
                               "SECTION_NAME, " +
                               "JOINING_DATE, " +
                               "EMPLOYEE_CODE, " +
                               "EID_YEAR, " +
                               "EID_TYPE_ID, " +
                               "EID_NAME, " +
                               "UNIT_ID, " +
                               "SECTION_ID, " +
                               "CARD_NO, " +
                               "TOTAL_MONTH, " +
                               "GROSS_SALARY, " +
                               "BASIC_SALARY, " +
                               "BONUS_PERCENT, " +
                               "BONUS_AMOUNT, " +
                                "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                               "UPDATE_DATE, " +
                               "HEAD_OFFICE_ID, " +
                               "BRANCH_OFFICE_ID, " +
                               "UNIT_SECTION, " +


                                "'In Word : ' " +
              "|| (SELECT   func_number_to_word (SUM (ROUND (BONUS_AMOUNT))) " +
