                           "WHERE   contract_id = '" + objReportDTO.ContractId + "'  AND ISSUE_DATE =  m.ISSUE_DATE " +
                           "AND AMENDMENT_ID =  '" + objReportDTO.AmendmentId + "' " +
                           "AND head_office_id = m.head_office_id " +
                           "AND branch_office_id = m.branch_office_id AND INCREASE_YN = 'Y') > 0 " +
                           " THEN 'Increasing ' " +
                           " ELSE 'Decreasing ' END " +
                           " || 'value of  USD ' " +
                            " ||(select AMENDMENT_DIFF_AMOUNT from contract_amount   WHERE   contract_id = '" + objReportDTO.ContractId + "'  AND ISSUE_DATE =  m.ISSUE_DATE AND AMENDMENT_ID =  '" + objReportDTO.AmendmentId + "' AND head_office_id = m.head_office_id AND branch_office_id = m.branch_office_id ) " +
                            " || ' after amendment, now total  value of this contract is USD ' || (SELECT  (SUM (TOTAL_AMOUNT_IN_USD)) FROM   CONTRACT_REPORT_DAILY WHERE contract_id = '" + objReportDTO.ContractId + "' and AMENDMENT_ID =  '" + objReportDTO.AmendmentId + "' AND ISSUE_DATE = m.ISSUE_DATE  AND head_office_id = m.head_office_id AND branch_office_id = m.branch_office_id ))  amendment_in_word, " +
