                        "CARD_NO, " +
                        "DESIGNATION_NAME, " +
                        "UNIT_ID, " +
                        "UNIT_NAME, " +
                        "SECTION_ID, " +
                        "SECTION_NAME, " +
                        "DESIGNATION_ID, " +
                        "ACTIVE_YN, " +


                        " (SELECT   GROSS_SALARY FROM   increment_basic_info_ADD_HO WHERE       employee_id = e.employee_id AND (increment_year = '" + objReportDTO.Year + "' - 4 ) " +
                        " AND head_office_id = '" + objReportDTO.HeadOfficeId + "'  )GROSS_SALARY_2013, " +

                         " (SELECT   GROSS_SALARY FROM   increment_basic_info_ADD_HO WHERE       employee_id = e.employee_id AND (increment_year = '" + objReportDTO.Year + "' - 3 ) " +
                        " AND head_office_id = '" + objReportDTO.HeadOfficeId + "'  )GROSS_SALARY_2014, " +

                         " (SELECT   GROSS_SALARY FROM   increment_basic_info_ADD_HO WHERE       employee_id = e.employee_id AND (increment_year = '" + objReportDTO.Year + "' -2 ) " +
