                        " (SELECT   REMARKS FROM   increment_proposal_ho WHERE       employee_id = e.employee_id AND (increment_year = '" + objReportDTO.Year + "' - 1 ) " +
                        " AND head_office_id = '" + objReportDTO.HeadOfficeId + "' ) REMARK_LAST, " +




                        " (SELECT   score FROM   increment_proposal_ho WHERE       employee_id = e.employee_id AND increment_year = '" + objReportDTO.Year + "' " +
                        " AND head_office_id = '" + objReportDTO.HeadOfficeId + "' ) SCORE_CURRENT, " +

                         " (SELECT   increment_amount FROM   increment_basic_info WHERE       employee_id = e.employee_id AND increment_year = '" + objReportDTO.Year + "' " +
                        " AND head_office_id = '" + objReportDTO.HeadOfficeId + "' ) INCREMENT_CURRENT, " +

                         " (SELECT   remarks FROM   increment_proposal_ho WHERE       employee_id = e.employee_id AND increment_year = '" + objReportDTO.Year + "' " +
                        " AND head_office_id = '" + objReportDTO.HeadOfficeId + "') REMARK_CURRENT, " +






                        "CASE " +
            "WHEN(SELECT   COUNT(* ) " +
             "       FROM   increment_basic_info " +
              "     WHERE       employee_id = e.employee_id " +
               "            AND increment_year = '" + objReportDTO.Year + "' " +

                  "         AND effect_date IS NOT NULL) > 0 " +
            "THEN  " +
             "  (SELECT   TO_CHAR(effect_date, 'dd/mm/yyyy') " +
              "    FROM   increment_basic_info " +
               "  WHERE       employee_id = e.employee_id " +
                "         AND increment_year = '" + objReportDTO.Year + "' " +
                 "        AND head_office_id = e.head_office_id) " +

            "ELSE " +
             "  (SELECT   TO_CHAR(effect_date, 'dd/mm/yyyy') " +
              "    FROM   S_INCREMENT_PROPOSAL_SETUP  " +
               "  WHERE       increment_year = '" + objReportDTO.Year + "' " +
                "         AND head_office_id = e.head_office_id " +
                 "        AND branch_office_id = e.branch_office_id) " +
         "END effect_date_current, " +

                        "JOINING_DATE, " +
