         "      FROM increment_basic_info i " +
          "    WHERE section_id = '" + objReportDTO.SectionId + "' " +
           "           AND(increment_year = '" + objReportDTO.Year + "' - 1) " +
            "          AND head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
             "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' " +
              "        AND EXISTS " +
               "             (SELECT   1 " +
                "               FROM   employee_basic " +
                 "             WHERE       employee_id = i.employee_id " +
                  "                    AND active_yn = 'Y' " +
                   "                   AND head_office_id = i.head_office_id " +
                    "                  AND branch_office_id = " +
                     "                       i.branch_office_id)) " +
      "   || ' Only ' total_inc_amount_in_word " +



                        " from VEW_RPT_INCREMENT_SUMMERY_HO e  where head_office_id = '" + objReportDTO.HeadOfficeId + "' ";






                    if (objReportDTO.CardNo.Length > 0)
                    {
                        sql = sql + "and card_no = '" + objReportDTO.CardNo + "' ";

                    }

                    if (objReportDTO.EmployeeId.Length > 0)
                    {
                        sql = sql + "and employee_id = '" + objReportDTO.EmployeeId + "' ";

                    }

                    if (objReportDTO.SectionId.Length > 0)
                    {
                        sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                    }
                    if (objReportDTO.UnitId.Length > 0)
                    {
                        sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";

                    }



                    //sql = sql + " order by to_number(card_no)";


                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "VEW_RPT_INCREMENT_SUMMERY_HO");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }
