        public DataSet productionReport(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT  'From ' || '" + objReportDTO.FromDate + "' START_DATE," +
                           "'To ' || '" + objReportDTO.ToDate + "' END_DATE," +
                           "HEAD_OFFICE_ID, " +
                           "HEAD_OFFICE_NAME, " +
                           "HEAD_OFFICE_ADDRESS, " +
                           "BRANCH_OFFICE_ID, " +
                           "BRANCH_OFFICE_NAME, " +
                           "BRANCH_OFFICE_ADDRESS, " +
                           "TRAN_ID, " +
                           "PRODUCTION_DATE, " +
                           "ORDER_QUANTITY, " +
                           "PO_NO, " +
                           "STYLE_NO, " +
                           "STYLE_ID, " +
                           "LINE_ID, " +
                           "LINE_NO, " +
                           "BUYER_ID, " +
                           "BUYER_NAME, " +
                           "COLOR_ID, " +
                           "COLOR_FULL_NAME, " +
                           "CUTTING_QUANTITY, " +
                           "CUTTING_DELIVERY, " +
                           "SEWING_INPUT, " +
                           "SEWING_OUTPUT, " +
                           "WASHING_SENT, " +
                           "WASHING_RECEIVED, " +
                           "POLY_QUANTITY, " +
                           "CARTON_QUANTITY, " +
                           "REMAINING_QUANTITY, " +
                           "FINALIZED_YN, " +
                           "UPDATE_BY, " +
                           "UPDATE_DATE " +

                        "from vew_daily_production  where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' ";


                    if (objReportDTO.FromDate.Length > 6 && objReportDTO.ToDate.Length > 6)
                    {

                        sql = sql + " and production_Date between to_date('" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and to_date('" + objReportDTO.ToDate + "', 'dd/mm/yyyy') ";
                    }

                    if (objReportDTO.PONo.Length > 0)
                    {

                        sql = sql + " and po_no = '" + objReportDTO.PONo + "' ";
                    }

                    if (objReportDTO.BuyerId.Length > 0)
                    {

                        sql = sql + " and buyer_id = '" + objReportDTO.BuyerId + "' ";
                    }



                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "vew_daily_production");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }
