        public DataSet rptProductionSheet(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT " +
                        "'Daily Production Sheet From ' ||  '" + objReportDTO.FromDate + "' || ' to ' ||  '" + objReportDTO.ToDate + "'  rpt_title, " +
                       "BUYER_NAME, " +

                       "HEAD_OFFICE_NAME, " +
                       "BRANCH_OFFICE_NAME, " +
                       "BRANCH_OFFICE_ADDRESS, " +
                       "LINE_ID, " +
                       "LINE_NAME, " +
                       "PRODUCTION_DATE, " +

                       "PO_NO, " +
                       "PO_ID, " +
                       "STYLE_ID, " +
                       "STYLE_NO, " +
                       "ORDER_QUANTITY, " +
                       "CUTTING_ISSUED_QUANTITY, " +
                       "CUTTING_DELIVERY_QUANTITY, " +
                       "SEWING_INPUT_QUANTITY, " +
                       "SEWING_OUTPUT_QUANTITY, " +
                       "WASH_SEND_QUANTITY, " +
                       "WASH_RECEIVED_QUANTITY, " +
                       "FINISHING_POLY_QUANTITY, " +
                       "FINISHING_CARTON_QUANTITY, " +
                       "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                       "UPDATE_DATE, " +
                       "HEAD_OFFICE_ID, " +
                       "BRANCH_OFFICE_ID, " +
                       "EXCESS " +

                       "from VEW_RPT_DAILY_PRODUCTION p where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "'  ";






                    if (objReportDTO.LineId.Length > 0)
                    {
                        sql = sql + "and LINE_ID = '" + objReportDTO.LineId + "' ";

                    }
                    if (objReportDTO.BuyerId.Length > 0)
                    {
                        sql = sql + "and BUYER_ID = '" + objReportDTO.BuyerId + "' ";

                    }
                    if (objReportDTO.POId.Length > 0)
                    {
                        sql = sql + "and PO_ID = '" + objReportDTO.POId + "' ";

                    }

                    if (objReportDTO.FromDate.Length > 6 && objReportDTO.ToDate.Length > 6)
                    {
                        sql = sql + "and PRODUCTION_DATE BETWEEN  to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy') and to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') ";

                    }



                    //sql = sql + " order by to_number(card_no)";


                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "VEW_RPT_DAILY_PRODUCTION");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }

