        public List<string> SearchPONo(string strInvoiceNo, string strBuyerId)
        {

            List<string> allInvoiceNo = new List<string>();

            string sql = "";

            sql = "SELECT " +

                     "TO_CHAR(NVL(PO_NO,''))PO_NO " +

               "FROM PO_ASSIGN WHERE (lower(PO_NO) like lower( '%" + strInvoiceNo + "%')  or upper(PO_NO)like upper('%" + strInvoiceNo + "%'))";

            if (strBuyerId.Length > 0)
            {
                sql = sql + "and BUYER_ID = '" + strBuyerId + "'";

            }
            sql = sql + "ORDER BY PO_NO";

            OracleCommand objCommand = new OracleCommand(sql);
            OracleDataReader objDataReader;

            using (OracleConnection strConn = GetConnection())
            {

                objCommand.Connection = strConn;
                strConn.Open();
                objDataReader = objCommand.ExecuteReader();
                try
                {
                    while (objDataReader.Read())
                    {
                        allInvoiceNo.Add(objDataReader.GetString(0));

                    }
                }
                catch (Exception ex)
                {
                    throw new Exception("Error : " + ex.Message);

                }

                finally
                {

                    strConn.Close();
                }

            }




            return allInvoiceNo;

        }

