                sql = sql + "and PO_NUMBER  =  '" + objReportDTO.PoNumber + "' ";

            }


            if (objReportDTO.FromDate.Length > 6 && objReportDTO.ToDate.Length > 6)
            {
                sql = sql + "and SHIPMENT_DATE BETWEEN to_date( '" + objReportDTO.FromDate + "', 'dd/mm/yyyy')  and to_date( '" + objReportDTO.ToDate + "', 'dd/mm/yyyy') ";

            }

            sql = sql + " order by to_number(tran_id)";

            OracleCommand objOracleCommand = new OracleCommand(sql);
            OracleDataAdapter objDataAdapter = new OracleDataAdapter();
            using (OracleConnection strConn = GetConnection())
            {
                try
                {
                    objOracleCommand.Connection = strConn;
                    strConn.Open();
                    //strConn.BeginTransaction();

                    objDataAdapter = new OracleDataAdapter(objOracleCommand);
                    dt.Clear();
                    //objOracleCommand.ExecuteNonQuery();
                    ds = new System.Data.DataSet();
                    objDataAdapter.Fill(ds, "VEW_PO_TRACKING_SHIP_DLV_DATE");
                    objDataAdapter.Dispose();
                    objOracleCommand.Dispose();
                }

                catch (Exception ex)
                {
                    throw new Exception("Error : " + ex.Message);

                }

                finally
                {

                    strConn.Close();
                }

            }




            return ds;
        }
