        public DataSet GetAccountHolderEncashSheet(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT " +
                          "REPORT_TITLE, " +
                           "HEAD_OFFICE_ID, " +
                           "HEAD_OFFICE_NAME, " +
                           "HEAD_OFFICE_NAME_BANGLA, " +
                           "HEAD_OFFICE_ADDRESS, " +
                           "BRANCH_OFFICE_ID, " +
                           "BRANCH_OFFICE_NAME, " +
                           "BRANCH_OFFICE_NAME_BANGLA, " +
                           "BRANCH_OFFICE_ADDRESS, " +
                           "EMPLOYEE_ID, " +
                           "EMPLOYEE_NAME, " +
                           "EMPLOYEE_NAME_BANGLA, " +
                           "CARD_NO, " +
                           "DESIGNATION_NAME, " +
                           "DESIGNATION_NAME_BANGLA, " +
                           "UNIT_ID, " +
                           "UNIT_NAME, " +
                           "UNIT_NAME_BANGLA, " +
                           "SECTION_ID, " +
                           "SECTION_NAME, " +
                           "SECTION_NAME_BANGLA, " +
                           "JOINING_DATE, " +
                           "LEAVE_YEAR, " +
                           "BASIC_SALARY, " +
                           "GROSS_SALARY, " +
                           "LEAVE_DAY, " +
                           "LEAVE_AMOUNT, " +
                           "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                           "UPDATE_DATE, " +
                           "unit_section, " +
                           "payment_amount_in_word, " +
                           "account_no " +

                       "from VEW_LEAVE_ENCASH_B_SHEET_STAFF  where  head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' and LEAVE_YEAR = '" + objReportDTO.Year + "' and account_no is not null ";



                    //if (objReportDTO.Year.Length > 0)
                    //{
                    //    sql = sql + "and SALARY_YEAR = '" + objReportDTO.Year + "' ";

                    //}

                    //if (objReportDTO.Month.Length > 0)
                    //{
                    //    sql = sql + "and SALARY_MONTH = '" + objReportDTO.Month + "' ";

                    //}


                    if (objReportDTO.UnitId.Length > 0)
                    {
                        sql = sql + "and unit_id = '" + objReportDTO.UnitId + "' ";

                    }

                    if (objReportDTO.SectionId.Length > 0)
                    {
                        sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                    }
                    if (objReportDTO.SectionId.Length > 0)
                    {
                        sql = sql + "and section_id = '" + objReportDTO.SectionId + "' ";

                    }
                    if (objReportDTO.UnitGroupId.Length > 0)
                    {
                        sql = sql + "and unit_group_id = '" + objReportDTO.UnitGroupId + "' ";

                    }
                    //sql = sql + " order by EMPLOYEE_NAME";


                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "VEW_LEAVE_SHEET_STAFF");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }
