       "TIFFIN_DAY, " +
       "LUNCH_DAY, " +
       "ABSENT_DAY, " +
       "OVER_TIME_HOUR, " +
       "OVER_TIME_RATE, " +
       "OVER_TIME_AMOUNT, " +
       "ATTENDENCE_FEE, " +
       "ABSENT_FEE, " +
       "MEDICAL_FEE, " +
       "HOUSE_RENT_FEE, " +
       "TAX_FEE, " +
       "CONVENCE_FEE, " +
       "FOOD_FEE, " +
       "EXTRA_FOOD_FEE, " +
       "ADVANCE_FEE, " +
       "ALLOWANCE_AMOUNT, " +
       "ARREAR_FEE, " +
       "GROSS_SALARY, " +
       "BASIC_SALARY, " +
       "PAYMENT_AMOUNT, " +
       "UPDATE_DATE, " +
       "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
       "SALARY_MONTH_NEW, " +
       "ABSENT_DEDUCT_EXTRA_FOOD_FEE,  " +
       "MONTH_DAY, " +
       "DESIGNATION_ID, " +
       "DESIGNATION_NAME, " +
       "CARD_NO, " +
       "MONTH_DAY, " +
       "DESIGNATION_BANGLA, " +
       "UNIT_NAME_BANGLA, " +
       "SECTION_NAME_BANGLA, " +
       "DUE_AMOUNT, " +

        "'In Word : ' " +
" || (SELECT   func_number_to_word (SUM (PAYMENT_AMOUNT)) " +
"    FROM   monthly_salary where " +
"        salary_year = '" + objReportDTO.Year + "' " +
"      AND salary_month = '" + objReportDTO.Month + "' " +
"      AND section_id =  s.section_id " +
"      AND unit_id =  s.unit_id " +
"     AND head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
"    AND branch_office_id = '" + objReportDTO.BranchOfficeId + "') " +
" || ' Only ' PAYMENT_AMOUNT_ENG, " +




             "CASE " +
             "    WHEN HEAD_OFFICE_ID = 441 " +
              "        AND (branch_office_id IN (107, 106, 109,105)) " +
               "  THEN " +
                "    'In Word : ' " +
                 "   || (SELECT   func_number_to_word(SUM (PAYMENT_AMOUNT) " +
                  "                                   + NVL (SUM (TAX_FEE), 0)) " +
                   "       FROM   monthly_salary " +

                     "            where salary_year = '" + objReportDTO.Year + "' " +
                      "           AND salary_month = '" + objReportDTO.Month + "' " +
                       "          AND head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                        "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "') " +
               "  ELSE " +
                "    'In Word : ' " +
                 "   || (SELECT   func_number_to_word (SUM (PAYMENT_AMOUNT)) " +
                  "        FROM   monthly_salary " +

                     "            where  salary_year = '" + objReportDTO.Year + "' " +
                      "           AND salary_month = '" + objReportDTO.Month + "' " +
                       "          AND head_office_id = '" + objReportDTO.HeadOfficeId + "' " +
                        "         AND branch_office_id = '" + objReportDTO.BranchOfficeId + "') " +
             " END " +
             " || ' Only ' PAYMENT_AMOUNT_ENG_TOTAL, " +
       "branch_office_id, " +
       "branch_office_address, " +
       "FOOD_ALLOWANCE_FEE, " +
       "FOOD_DEDUCT_FEE " +

       "from VEW_SALARY_SHEET_HO S where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' AND salary_year = '" + objReportDTO.Year + "' and salary_month = '" + objReportDTO.Month + "' ";






