        public DataSet IncrementProposalReqSummary(ReportDTO objReportDTO)
        {
            try
            {

                DataSet ds = null;
                DataTable dt = new DataTable();
                try
                {
                    string sql = "";
                    sql = "SELECT " +
                          //new
                          "'Increment Proposal Worker Summary Sheet, ' || (Select to_char(effect_date, 'yyyy') from S_INCREMENT_PROPOSAL_SETUP where INCREMENT_YEAR = ('" + objReportDTO.Year + "' ) AND head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "' and employee_type_id = '2') MONTH_YEAR, " +
                           //old
                           //" 'Increment Proposal Worker Summary Sheet , '  || '" + objReportDTO.Year + "'  MONTH_YEAR, " +
                           "SECTION_ID, " +
                           "UNIT_NAME, " +
                            "UNIT_GROUP_NAME, " +
                           "SECTION_NAME_BANGLA, " +
                           "INCREMENT_YEAR, " +
                           "GROSS_SALARY, " +
                           "BASIC_SALARY, " +
                           "INCREMENT_AMOUNT, " +
                           "(select employee_full_name from login_employee where EMPLOYEE_ID = '" + objReportDTO.UpdateBy + "') UPDATE_BY, " +
                           "UPDATE_DATE, " +
                           "HEAD_OFFICE_NAME_BANGLA, " +
                           "BRANCH_OFFICE_ID, " +
                           "BRANCH_OFFICE_NAME_BANGLA, " +
                           "HEAD_OFFICE_ID, " +
                           "TOTAL_EMPLOYEE, " +
                           "TOTAL_INCREMENT_AMOUNT, " +
                           "TOTAL_INCREMENT_EMPLOYEE, " +
                           "TOTAL_INCREMENT_AMOUNT, " +
                           "INCREMENT_PERCENT, " +
                           "INCREMENT_AMOUNT_PER_HEAD, " +
                           "five_percent_gross_salary, " +
                           "five_percent_emp, " +
                           "TOTAL_FIVE_PERCENT " +


                       "from VEW_INC_PRO_WORKER_SUM_ENG  where head_office_id = '" + objReportDTO.HeadOfficeId + "' AND branch_office_id = '" + objReportDTO.BranchOfficeId + "'  AND  increment_year = '" + objReportDTO.Year + "' ";

                    if (objReportDTO.UnitGroupId.Length > 0)
                    {
                        sql = sql + "and unit_group_id = '" + objReportDTO.UnitGroupId + "' ";

                    }
                    OracleCommand objOracleCommand = new OracleCommand(sql);
                    OracleDataAdapter objDataAdapter = new OracleDataAdapter();
                    using (OracleConnection strConn = GetConnection())
                    {
                        try
                        {
                            objOracleCommand.Connection = strConn;
                            strConn.Open();
                            //strConn.BeginTransaction();

                            objDataAdapter = new OracleDataAdapter(objOracleCommand);
                            dt.Clear();
                            //objOracleCommand.ExecuteNonQuery();
                            ds = new System.Data.DataSet();
                            objDataAdapter.Fill(ds, "VEW_INC_PRO_WORKER_SUM_ENG");
                            objDataAdapter.Dispose();
                            objOracleCommand.Dispose();
                        }

                        catch (Exception ex)
                        {
                            throw new Exception("Error : " + ex.Message);

                        }

                        finally
                        {

                            strConn.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    throw ex;
                }

                return ds;
            }
            catch (Exception ex)
            {
                throw ex;
            }

        }

